from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(11,'proportionnalite','Proportionnalité et pourcentages','2 · Algèbre et grandeurs',
'Coefficient · Retour à l’unité · Échelle · Vitesse moyenne',
['Reconnaître et représenter une proportionnalité.','Utiliser proportions et pourcentages.','Résoudre des problèmes de prix, recettes et échelles.'],['Quotients et fractions.'],[
page(1,'Un même multiplicateur',
bloc('definition',r'Deux grandeurs sont proportionnelles si les valeurs de l’une s’obtiennent en multipliant les valeurs correspondantes de l’autre par un même nombre : le coefficient de proportionnalité.'),
tableau(['Masse (kg)','1','2','3,5'],[['Prix (euros)','2,4','4,8','8,4']]),
bloc('savoirfaire',r'On peut revenir à l’unité, additionner deux colonnes ou multiplier une colonne. Pour six personnes à partir d’une recette pour quatre, multiplier les quantités par $6/4=1{,}5$.','Plusieurs procédures'),
r'@FIG:cours-proportion@',
bloc('attention',r'Un supplément fixe, un tarif par paliers ou une remise selon la quantité peut rompre la proportionnalité. Il faut vérifier le modèle avant de choisir la méthode.')),
page(2,'Pourcentages et changements d’échelle',
bloc('definition',r'$p\,\%$ signifie $p/100$. Les $15\,\%$ de 80 valent $(80:100)\times15=12$. Pour exprimer une part de 7 sur 20 en pourcentage, calculer $7/20=35/100=35\,\%$.'),
bloc('savoirfaire',r'À l’échelle $1:200$, une longueur de 1 cm représente 200 cm réels. Utiliser la même unité pour le dessin et la réalité avant de multiplier ou diviser.','Échelles'),
bloc('exemple',r'À vitesse constante de 60 km/h, 2,5 heures correspondent à $60\times2{,}5=150$ km. Pour un déplacement quelconque, la vitesse moyenne est distance totale divisée par durée totale. 30 minutes correspondent à 0,5 heure.'),
bloc('propriete',r'Dans un repère, une proportionnalité donne des points alignés sur une droite passant par l’origine. Pour des données discrètes, on place les points sans inventer de valeurs intermédiaires ; leur alignement avec l’origine caractérise la proportionnalité du tableau.'))
],[
E('Un coefficient',r'3 kg de fruits coûtent 7,50 euros, au même prix au kg. Trouver le coefficient permettant de passer des kg aux euros.',r'$7{,}50:3=\res{2{,}50}$ euros par kg. Le prix s’obtient en multipliant la masse par 2,5.','Revenir à une unité.','assert Rational("7.5")/3==Rational("2.5")'),
E('Une recette doublée',r'Pour quatre personnes, il faut 180 g de riz. Combien pour huit personnes ?',r'On double le nombre de personnes, donc la quantité : $180\times2=\res{360\ \mathrm g}$.','Multiplier les deux grandeurs par le même nombre.','assert 180*8//4==360'),
E('Un pourcentage simple',r'Calculer 10 %, 50 % et 1 % de 240.',r'On obtient $\res{24}$, $\res{120}$ et $\res{2{,}4}$. Ce sont respectivement un dixième, une moitié et un centième.','Utiliser les parts repères.','assert Rational(10,100)*240==24 and Rational(50,100)*240==120 and Rational(1,100)*240==Rational("2.4")'),
E('Proportion ou effectif',r'Parmi 30 élèves, 12 viennent à pied. Quel pourcentage cela représente-t-il ?',r'$12/30=2/5=40/100$. Cela représente $\res{40\,\%}$ de la classe.','Rapporter la part au total.','assert Rational(12,30)==Rational(40,100)'),
E('Un tableau à reconnaître',r'Un magasin vend des lots de stylos identiques. D’après le tableau, le prix payé est-il proportionnel au nombre de lots achetés ?'+tableau(['Nombre de lots','1','2','3'],[['Prix (euros)','4','8','12']]),r'Les quotients du prix par le nombre de lots valent $4/1=8/2=12/3=4$. Le prix s’obtient en multipliant le nombre de lots par 4 : $\res{oui}$, le prix est proportionnel au nombre de lots, avec un coefficient de 4 euros par lot.','Comparer les quotients correspondants.','assert [Rational(b,a) for a,b in [(1,4),(2,8),(3,12)]]==[4,4,4]'),
E('Une recette pour six',r'Une recette pour quatre demande 250 g de farine et 20 cL de lait. Donner les quantités pour six.',r'Le coefficient est $6/4=1{,}5$. Il faut $\res{375\ \mathrm g}$ de farine et $\res{30\ \mathrm{cL}}$ de lait.','Employer le même coefficient pour chaque ingrédient.','assert Rational(6,4)*250==375 and Rational(6,4)*20==30'),
E('Une remise',r'Un article de 80 euros bénéficie d’une réduction de 15 %. Calculer la réduction puis le prix payé.',r'La réduction est $(80:100)\times15=12$ euros. On paie $80-12=\res{68}$ euros. 15 % désigne ici la réduction, pas le prix final.','Calculer la part puis la soustraire.','assert Rational(15,100)*80==12 and 80-12==68'),
E('Une échelle de plan',r'Un mur mesure 4,8 m. Quelle longueur a-t-il sur un plan à l’échelle $1:100$ ?',r'$4{,}8$ m $=480$ cm. La longueur dessinée est $480:100=\res{4{,}8\ \mathrm{cm}}$.','Convertir avant d’appliquer l’échelle.','assert Rational("4.8")*100/100==Rational("4.8")',figure='prop-8'),
E('Vitesse moyenne',r'Un cycliste parcourt 27 km en 1 h 30. Quelle est sa vitesse moyenne en km/h ?',r'$1$ h $30=1{,}5$ h. La vitesse moyenne est $27:1{,}5=\res{18\ \mathrm{km/h}}$. $1{,}30$ heure ne représente pas 1 h 30.','Exprimer la durée en heures décimales.','assert Rational(27)/Rational("1.5")==18'),
E('Une situation non proportionnelle',r'Une livraison coûte 4 euros fixes plus 2 euros par colis. Le prix est-il proportionnel au nombre de colis ?',r'Un colis coûte 6 euros, deux coûtent 8 euros. Doubler le nombre ne double pas le prix. La situation est $\res{non\ proportionnelle}$.','Tester un doublement.','assert 4+2==6 and 4+2*2==8 and 2*6!=8'),
E('Lire des points proportionnels',r'Le graphique donne le prix de tickets identiques. Lire le prix de trois tickets, puis trouver le prix unitaire.',r'Le point d’abscisse 3 a pour ordonnée 7,5 euros. Un ticket coûte $7{,}5:3=\res{2{,}50}$ euros. Les points et l’origine sont alignés.','Lire les axes puis revenir à l’unité.','assert Rational("7.5")/3==Rational("2.5")',figure='prop-11'),
E('Retrouver un effectif',r'Dans un groupe, 18 personnes représentent 30 % du total. Combien y a-t-il de personnes ?',r'10 % correspondent à $18:3=6$ personnes. 100 % correspondent à $6\times10=\res{60}$ personnes. Contrôle : 30 % de 60 vaut 18.','Retrouver une part repère.','assert 18//3*10==60 and Rational(30,100)*60==18'),
E('Comparer deux promotions',r'Pour un article à 60 euros, A propose 20 % de réduction ; B retire 10 euros. Quelle offre est la plus avantageuse ?',r'A retire 12 euros et fait payer 48 euros. B fait payer 50 euros. L’offre $\res A$ est moins chère de 2 euros.','Comparer les prix finaux.','assert 60*(1-Rational(20,100))==48 and 60-10==50'),
E('Deux trajets',r'On parcourt 12 km en 30 minutes puis 18 km en 1 h 30. Calculer la vitesse moyenne sur l’ensemble du trajet.',r'Distance totale : $12+18=30$ km. Durée totale : $0{,}5+1{,}5=2$ h. Vitesse moyenne : $30:2=\res{15\ \mathrm{km/h}}$. La moyenne simple de 24 et 12 ne convient pas, car les durées diffèrent.','Diviser les totaux.','assert Rational(12+18,Rational("0.5")+Rational("1.5"))==15'),
E('Une carte et un détour',r'À l’échelle $1:25000$, un itinéraire mesure 6,4 cm sur la carte. Un détour ajoute 15 % de la distance représentée. Quelle distance réelle parcourra-t-on ?',r'$6{,}4\times25000=160000$ cm, soit 1,6 km. Le détour vaut $15\,\%$ de 1,6 km, soit 0,24 km. La distance totale est $\res{1{,}84\ \mathrm{km}}$.','Mettre les unités au même niveau puis appliquer la proportion.','assert Rational("6.4")*25000/100000==Rational("1.6") and Rational("1.6")*(1+Rational(15,100))==Rational("1.84")',figure='prop-15')
],reperes=['Coefficient et procédures de proportionnalité','Proportions et pourcentages','Prix, recettes, échelles et vitesses','Tableaux et caractérisation graphique'],deco='calcul')

chapitre(12,'reperage','Repérage et grandeurs en fonction d’une autre','2 · Algèbre et grandeurs',
'Repère orthogonal · Coordonnées · Tableaux · Graphiques',
['Lire et placer des points dans un repère orthogonal.','Produire un tableau à partir d’une formule.','Lire une dépendance et reconnaître la proportionnalité.'],['Relatifs et formules.'],[
page(1,'Deux coordonnées dans un ordre précis',
bloc('definition',r'Un repère orthogonal comporte deux axes perpendiculaires : l’axe horizontal des abscisses, l’axe vertical des ordonnées. Un point $A(3;-2)$ se repère par 3 sur le premier axe puis $-2$ sur le second. Les unités des axes peuvent être différentes.'),
r'@FIG:cours-repere@',
bloc('savoirfaire',r'Pour lire un point, projeter horizontalement et verticalement sur les axes. Pour le placer, partir de l’origine, suivre l’abscisse puis l’ordonnée. Sur l’axe horizontal, l’ordonnée est 0 ; sur l’axe vertical, l’abscisse est 0.','Lire et placer'),
bloc('attention',r'$A(3;-2)$ et $B(-2;3)$ sont généralement différents. Les coordonnées sont un couple ordonné.')),
page(2,'Décrire une dépendance',
bloc('definition',r'Dire « le prix en fonction de la durée » signifie que la durée sert de donnée d’entrée et que le prix dépend de cette durée. On peut employer une formule, un tableau ou un graphique, sans étude générale des fonctions.'),
tableau(['Durée $t$ (h)','0','1','2','4'],[['Prix $3t+5$ (euros)','5','8','11','17']]),
r'@FIG:cours-dependance@',
bloc('savoirfaire',r'Lire les titres, les unités et les pas des graduations. Les points d’un tableau de données discrètes ne sont pas forcément à relier. Une formule permet de construire le tableau ; un graphique permet de visualiser les variations.','Passer d’une représentation à l’autre'),
bloc('attention',r'Des points alignés ne suffisent pas pour une proportionnalité : la droite doit aussi passer par l’origine. Une courbe croissante n’est pas forcément une droite.'))
],[
E('Lire deux points',r'Lire les coordonnées de A et B.',r'On lit d’abord l’abscisse puis l’ordonnée : $\res{A(2;3)}$ et $\res{B(-3;1)}$.','Projeter sur chacun des axes.','assert 2>0 and 3>0 and -3<0',figure='rep-1'),
E('Placer un point',r'Placer $C(-2;-3)$ dans le repère.',r'Aller deux unités à gauche puis trois vers le bas. Le point est dans la zone où les deux coordonnées sont négatives.','Suivre l’ordre abscisse puis ordonnée.','assert -2<0 and -3<0',figure='rep-2'),
E('Sur les axes',r'Placer $D(0;3)$ et $E(-4;0)$.',r'D est sur l’axe vertical, E sur l’axe horizontal. Une coordonnée nulle supprime le déplacement dans la direction correspondante.','Utiliser le rôle du zéro.','assert 0==0 and -4<0 and 3>0',figure='rep-3'),
E('Inverser les coordonnées',r'Placer $F(1;3)$ et $G(3;1)$. Sont-ils confondus ?',r'Leurs abscisses et ordonnées diffèrent ; les deux points sont $\res{distincts}$. Les coordonnées se lisent dans un ordre fixé.','Ne pas permuter les axes.','assert (1,3)!=(3,1)',figure='rep-4'),
E('Lire une valeur de graphique',r'La courbe donne une température en fonction de l’heure. Quelle température lit-on à 2 h ?',r'À l’abscisse 2, on rejoint la courbe puis l’axe vertical : $\res{10\,^\circ\mathrm C}$.','Lire l’ordonnée associée.','assert 6+2*2==10',figure='rep-5'),
E('Construire un tableau',r'Le prix en euros est $2t+4$, avec $t$ en heures. Donner les prix pour $t=0,1,3$ puis placer les points.',r'On obtient $\res{4,\ 6,\ 10}$ euros ; les points sont $(0;4)$, $(1;6)$ et $(3;10)$. Les valeurs calculées sont ajoutées dans le repère.','Substituer chaque entrée.','assert [2*t+4 for t in [0,1,3]]==[4,6,10]',figure='rep-6'),
E('Une courbe de carré',r'Pour un carré de côté $c$ cm, l’aire est $c^2$. Compléter pour $c=0,1,2,3$, puis placer les points. Sont-ils alignés ?',r'Les aires valent $\res{0,1,4,9}$ cm$^2$. Les points $(0;0)$, $(1;1)$, $(2;4)$ et $(3;9)$ ne sont pas alignés : l’aire n’est pas proportionnelle au côté.','Calculer avant de tracer.','assert [c*c for c in [0,1,2,3]]==[0,1,4,9] and 4!=2*1',figure='rep-7'),
E('Coordonnées décimales',r'Placer $H(-1{,}5;2{,}5)$ et $I(2{,}5;-0{,}5)$ sur le quadrillage gradué par demi-unités.',r'Chaque petit intervalle vaut 0,5. H est à trois pas à gauche et cinq vers le haut ; I à cinq pas à droite et un vers le bas.','Adapter les déplacements au pas du quadrillage.','assert Rational(-3,2)==Rational("-1.5") and Rational(5,2)==Rational("2.5")',figure='rep-8'),
E('Lire plusieurs moments',r'Le graphique donne un volume d’eau. Lire le volume à 0, 2 et 5 minutes. Sur quelle période reste-t-il constant ?',r'On lit $\res{10,\ 30,\ 20\ \mathrm L}$. Le segment horizontal de 2 à 4 minutes indique un volume constant de 30 L pendant cette période.','Distinguer hausse, palier et baisse.','assert 10+10*2==30 and 30-10*(5-4)==20',figure='rep-9'),
E('Des points alignés',r'Les points du graphique sont alignés. La relation est-elle proportionnelle ? Justifier avec l’origine.',r'La droite passe par $(0;3)$, et non par l’origine. La relation est $\res{non\ proportionnelle}$ : pour une entrée nulle, la sortie vaut 3.','Contrôler le passage par l’origine.','assert (2*x+3).subs(x,0)==3!=0',figure='rep-10'),
E('Un rectangle dans le plan',r'A, B et C sont trois sommets consécutifs d’un rectangle : $A(-3;-1)$, $B(2;-1)$, $C(2;3)$. Placer le quatrième sommet D.',r'Les côtés suivent les axes. D a l’abscisse de A et l’ordonnée de C : $\res{D(-3;3)}$. Les côtés opposés sont parallèles.','Croiser les deux coordonnées utiles.','assert (2-(-3))*(3-(-1))==20',figure='rep-11'),
E('Retrouver une formule',r'Un parking coûte 5 euros fixes puis 2 euros par heure. Donner le prix en fonction de $t$, puis lire le prix pour 4 h sur le graphique.',r'La formule est $\res{2t+5}$. Pour 4 h, $2\times4+5=\res{13}$ euros. Le graphique donne le même résultat.','Relier la formule à une lecture.','assert (2*x+5).subs(x,4)==13',figure='rep-12'),
E('Comparer deux tarifs',r'A coûte $3t$ euros ; B coûte $t+6$ euros. Pour les durées entières de 0 à 5 h, calculer les prix et repérer quand ils sont égaux.',r'A donne $0,3,6,9,12,15$ ; B donne $6,7,8,9,10,11$. Les prix sont égaux pour $\res{3\ \mathrm h}$ : 9 euros. Pour 2 h, A est moins cher ; pour 4 h, B l’est.','Comparer les sorties pour une même entrée.','assert [t for t in range(6) if 3*t==t+6]==[3]',figure='rep-13'),
E('Lire une tendance sans extrapoler',r'Le nuage de points donne des observations à 1, 2, 3 et 4 minutes. Peut-on affirmer la valeur à 5 minutes ? La relation observée est-elle proportionnelle ?',r'Les points connus sont $(1;2)$, $(2;5)$, $(3;5)$, $(4;8)$. Ils ne sont pas alignés avec l’origine : ce n’est pas une proportionnalité. Sans règle ou mesure supplémentaire, la valeur à 5 minutes est $\res{indéterminée}$.','Séparer observations et modèle supposé.','assert Rational(2,1)!=Rational(5,2)',figure='rep-14'),
E('Une réserve qui baisse',r'Une réserve contient 24 L et perd régulièrement 3 L par minute, jusqu’à être vide. Produire un tableau pour 0, 2, 4, 6 et 8 minutes ; écrire une formule et interpréter sa limite d’utilisation.',r'Les volumes sont $\res{24,18,12,6,0}$ L. La formule est $\res{24-3t}$ pour $0\le t\le8$. Après huit minutes, le réservoir est vide : prolonger la droite donnerait des volumes négatifs sans sens pour cette situation.','Préciser le domaine où le modèle décrit la situation.','assert [24-3*t for t in [0,2,4,6,8]]==[24,18,12,6,0] and 24-3*9<0',figure='rep-15')
],reperes=['Lire et placer des coordonnées','Formule et tableau de valeurs','Courbe, nuage et dépendance','Proportionnalité graphique et limites du modèle'],deco='geometrie')
